import json,pathlib
R=pathlib.Path('review'); out=[]
def add(key,severity,file,line,summary,scenario,script,fix,log):
 out.append(dict(id=key,severity=severity,file=file,line=line,location=f'{file}:{line}',summary=summary,failure_scenario=scenario,how_to_reproduce=f'在 D:/eab-wt/g6f 运行：$env:PYTHONDONTWRITEBYTECODE="1"; python -X utf8 {script}',repro_script=script,suggested_fix=fix,verified_output=pathlib.Path(log).read_text(encoding='utf-8-sig'),evidence_log=log,origin='中断前已有脚本/初步输出，本次自行重跑确认'))
add('root_dual_extreme','major','src/eab/dual.py',85,'Dual 除法和 atan2 在中间平方/乘积溢出或下溢时给出错误导数，即使输入与正确答案全部有限。','Dual(1e200,(1e200,))/1e200 应为值1、导数1，实得导数inf；尺度1e-200实得0而非1。atan2(Dual(1e200,(0,)),Dual(1e200,(1,))) 导数应为-5e-201，实得-0.0；1e-200版反而ZeroDivisionError。窄极端尺度范围，故major，不将普通算术误差冒充核心精确谓词错。','review/repro/root_dual_scaling.py','采用尺度规整的商/atan2导数表达式，避免先形成a*ov、x²+y²；若无法得到可信有限输出则响亮失败；补单位缩放与指数跨度门。','review/logs/root_dual_scaling_resume.log')
add('root_dual_power_zero','minor','src/eab/dual.py',107,'Dual ** 0 在零底数上错误抛出 ZeroDivisionError，而该运算是常数1、导数0。','Dual(0.,(1.,)) ** 0. 求 c=p*v**(p-1) 时先计算0**-1抛错；同API对非零底数正确返回Dual(1,(0,))。','review/repro/root_boundary_contracts.py','p==0作为恒等常数幂处理，返回同宽全零导数；增加零底数/零指数闭式边界门。','review/logs/root_boundary_contracts.log')
add('root_lp_zero_witness','minor','src/eab/lp.py',412,'零约束 OPTIMAL LP 快路遗漏 exact_x/exact_y，与一般最优结果精确见证接口不一致。','solve([],[],[0.,1.])及maximize([],[],[0.,-1.])状态/浮点答案正确，但exact_x=None、exact_y=None；应至少输出(Fraction(0),Fraction(0))与空tuple。一行参考LP正常携带见证。该项不是错误最优值。','review/repro/root_boundary_contracts.py','在m==0的optimal分支填零原始有理向量和空对偶向量，补所有optimal分支字段契约门。','review/logs/root_boundary_contracts.log')
add('root_margin_projection','major','src/eab/margin.py',491,'凸入口块距离与法向辅助 API 先舍入全局投影再相减，工程坐标下将可表达真实正距离答成 0、外法向答成 None。','精确盒 E=[T+s,T+3s]×[-s,s]^2，s=1e-9、T=1e8，点 x=(T,0,0)。独立区间积距离 s、投影 (T+s,0,0)、法向 (-1,0,0)；实际 distance=0、normal=None。相同模型移回原点时全部正确；这里 Fraction 保存合法微尺寸，并非 float 输入已塌缩。默认 body_distance 状态不受本脚本直接影响，缺陷在公开辅助 API 和所谓凸距离独立 oracle。','review/repro/root_margin_projection.py','保留相对投影向量的精确数据，直接由其平方范数计算距离/法向，不从舍入的全局投影坐标反减；公开点输出若是 float 视图，需另给精确点见证或声明表示界限；补单位和大平移门。','review/logs/root_margin_projection.log')
out[-1]['origin']='本次新增独立区间积反例并自行运行确认，不是上次沿用结论'
